import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"用 Electron 接入已有 Web 客户端","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/electron-shell","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/electron-shell.md","filePath":"tutorials/electron-shell.md"}'),o={name:"tutorials/electron-shell.md"};function n(p,e,l,r,c,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="用-electron-接入已有-web-客户端" tabindex="-1">用 Electron 接入已有 Web 客户端 <a class="header-anchor" href="#用-electron-接入已有-web-客户端" aria-label="Permalink to &quot;用 Electron 接入已有 Web 客户端&quot;">​</a></h1><p>自己的后端 API 和 Web 页面完成后，可以让 Electron 加载同一套页面、生成 SDK 与 Session 协议。桌面壳只负责平台接线，不增加另一套业务或授权规则；它没有离线编辑能力。</p><p>前提是完成<a href="./../getting-started/quickstart">快速开始</a>、客户端能调用自己的后端，且机器具有 Electron 所需的桌面依赖与显示环境。以下命令在仓库根目录运行。</p><h2 id="加载已有应用" tabindex="-1">加载已有应用 <a class="header-anchor" href="#加载已有应用" aria-label="Permalink to &quot;加载已有应用&quot;">​</a></h2><p>在一个终端启动应用，另一个终端打开壳：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span></code></pre></div><p>默认 Web 地址是 <code>http://127.0.0.1:15400</code>，通过 <code>.env</code> 的 <code>SAAS_DESKTOP_ORIGIN</code> 或 <code>WEB_PORT</code> 调整。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/desktop/src/main.ts" target="_blank" rel="noreferrer">主进程</a>加载这个同源入口；<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/web/src/router.tsx" target="_blank" rel="noreferrer">Web Router</a>和共享页面负责业务。先验证登录、自己的资源读取和一个写入请求，重启壳后再读同一资源。</p><p>Cookie 保存在独立持久分区 <code>persist:saas-desktop</code>，不与系统浏览器共享登录。退出登录撤销当前服务端 Session；只有使用同一 Session 的客户端会一起失效，另一个独立登录的浏览器 Session 不会因此被撤销。</p><h2 id="保持-ipc-的能力边界" tabindex="-1">保持 IPC 的能力边界 <a class="header-anchor" href="#保持-ipc-的能力边界" aria-label="Permalink to &quot;保持 IPC 的能力边界&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/desktop/src/preload.ts" target="_blank" rel="noreferrer">preload</a>与 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/desktop/src/ipc-contract.ts" target="_blank" rel="noreferrer">IPC 合同</a>提供壳版本/平台、重试加载、下载目录、下载事件和语言/主题偏好。两端都校验载荷；业务对象、凭据、Session secret 和文件字节不通过 IPC。</p><p>窗口固定开启 <code>contextIsolation</code> 和 <code>sandbox</code>，关闭 <code>nodeIntegration</code>，禁用 webview。导航只允许应用同源，外部 http/https 链接交给系统浏览器；弹窗、网站权限请求与其他 scheme 被拒绝，证书错误不放行。增加本地平台能力时先定义窄的 IPC 类型与校验，而不是暴露任意 Node 调用。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/web/src/desktop-preferences.tsx" target="_blank" rel="noreferrer">desktop-preferences.tsx</a>只在壳中镜像语言和主题两个枚举，以便 <code>file://</code> 错误页延续偏好。它不承载账号或业务数据，浏览器中为空操作。</p><h2 id="接入深链与下载" tabindex="-1">接入深链与下载 <a class="header-anchor" href="#接入深链与下载" aria-label="Permalink to &quot;接入深链与下载&quot;">​</a></h2><p>深链形如 <code>saas://open/notifications</code>；把 <code>/notifications</code> 换成自己的已注册绝对路径即可。解析器拒绝外部 URL、协议相对路径、反斜杠和原始空白；单实例锁把合法目标送到现有窗口。导航后仍由目标 API 重新鉴权，深链不是访问凭据。</p><p>应用同源页面发起的下载进入系统下载目录的 <code>SaasTemplate</code> 子目录，可通过 <code>SAAS_DESKTOP_DOWNLOADS_DIR</code> 覆盖。主进程清洗文件名，并对重名追加序号；跨源页面下载被取消。自己的 Files 客户端先经后端授权取得字节，再由页面触发下载，文件内容不进入 IPC。</p><h2 id="失败与检查" tabindex="-1">失败与检查 <a class="header-anchor" href="#失败与检查" aria-label="Permalink to &quot;失败与检查&quot;">​</a></h2><p>断网或渲染进程崩溃会显示本地错误页；“重新连接”回到失败前的应用地址。错误页使用壳保存的语言与主题。实际检查应包含加载失败、重试、非法深链和跨源下载拒绝：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/desktop/src/ipc-contract.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @saas/desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop-smoke</span></span></code></pre></div><p>合同测试不需要 GUI。<code>desktop-smoke</code> 创建真实隔离应用栈，用 Playwright 驱动 Electron，检查会话、导航、下载与错误恢复；需要显示环境或 xvfb。自己的业务页面应补一条定向旅程，完整角色矩阵由后端测试承担。</p><p>纯后端或文档正文修改无需运行 Electron。只有修改平台接线或交付桌面旅程时选择这些检查。安装包、自动更新与平台签名尚未提供，构建出的 <code>dist/main.cjs</code> 需要另接 Electron 打包流程。</p><p>下一步：<a href="./add-example">应用壳贡献合同</a>；长期客户端资源观察使用独立的长测，而非文档检查。</p><hr><p>源码版本：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/tutorials/20-electron-shell.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,24)])])}const k=a(o,[["render",n]]);export{b as __pageData,k as default};
